await readFile('bin/report.js');
// the formatter's name comes from the edit-lib step's output, not from a guess
const lib = dependencies['edit-lib'];
const fn = lib.facts.find((f) => f.key === 'csvFunction').value;
console.log('formatter from edit-lib:', fn);
const src = "#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { formatCsv, formatText, summarize } from '../src/report.js';

// report [--format text|csv] [file.json]: totals per region of a sales file (default data/sales.json).
const args = process.argv.slice(2);
let format = 'text';
let file = new URL('../data/sales.json', import.meta.url);
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--format') format = args[++i];
  else file = args[i];
}
const summary = summarize(JSON.parse(readFileSync(file, 'utf8')));
if (format === 'text') process.stdout.write(formatText(summary));
else if (format === 'csv') process.stdout.write(formatCsv(summary));
else {
  process.stderr.write(`unknown format ${format}\n`);
  process.exit(2);
}
";
await writeFile('bin/report.js', src.split('formatCsv').join(fn));
const v = await runVerify();
return { facts: [{ key: 'changedFiles', value: ['bin/report.js'] }, { key: 'formatter', value: fn }, { key: 'verifyExitAfterEdit', value: v.exitCode }] };
